package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct {
	ScAcct  string
	ScPrin  decimal.Decimal
	ScRate  decimal.Decimal
	ScYears int64
}

var WsEofFlag string = "N"
var WsBal decimal.Decimal = decimal.NewFromInt(0)
var WsYear int64 = 0
var WsCount int64 = 0
var WsBalEd string = ""

var InputDone bool = false
var SchedRecVar SchedRec

var schedFile *os.File
var schedReader *bufio.Scanner
var schedLines []string
var schedIdx int

func formatWsBalEd(v decimal.Decimal) string {
	// PIC ZZ,ZZZ,ZZ9.99 width 13, 8 integer digits, 2 decimal
	// Truncate/round already done; just format.
	// Ensure scale 2
	v = v.Truncate(2)
	// Handle negative? not needed but support
	neg := v.IsNegative()
	if neg {
		v = v.Neg()
	}
	// Get integer part and fractional
	// Use string representation with 2 decimal places
	s := v.StringFixed(2) // e.g. "1234.56"
	parts := strings.Split(s, ".")
	intPart := parts[0]
	fracPart := "00"
	if len(parts) > 1 {
		fracPart = parts[1]
		if len(fracPart) < 2 {
			fracPart = fracPart + strings.Repeat("0", 2-len(fracPart))
		} else if len(fracPart) > 2 {
			fracPart = fracPart[:2]
		}
	}
	// Keep low-order 8 integer digits if overflow
	if len(intPart) > 8 {
		intPart = intPart[len(intPart)-8:]
	}
	// Pad left with zeros to 8
	intPart = strings.Repeat("0", 8-len(intPart)) + intPart
	// intPart now 8 chars, positions 0..7
	// picture integer: Z Z , Z Z Z , Z Z 9  (commas at after 2 and 5)
	// Build formatted integer with commas
	// positions:
	// 0:Z 1:Z 2:',' 3:Z 4:Z 5:Z 6:',' 7:Z 8:Z 9:'9'
	// We'll create array of 11 chars for integer part including commas
	// Actually ZZ,ZZZ,ZZ9 => 8 digits + 2 commas =10 chars
	intDigits := intPart // 8
	formattedInt := make([]byte, 10)
	// map
	formattedInt[0] = intDigits[0]
	formattedInt[1] = intDigits[1]
	formattedInt[2] = ','
	formattedInt[3] = intDigits[2]
	formattedInt[4] = intDigits[3]
	formattedInt[5] = intDigits[4]
	formattedInt[6] = ','
	formattedInt[7] = intDigits[5]
	formattedInt[8] = intDigits[6]
	formattedInt[9] = intDigits[7]

	// Z suppression: leading zeros become spaces, commas in suppressed zone become spaces
	// Determine last Z position (the digit before the final 9). The final 9 is formattedInt[9]
	// Z positions are indices 0,1,3,4,5,7,8
	zIndices := []int{0, 1, 3, 4, 5, 7, 8}
	// For each Z index in order, if digit is '0' and all previous digit positions (excluding commas) are already suppressed (i.e. were zero and suppressed), then suppress.
	// Simpler: scan digit positions in order of digits; suppress leading zeros among Z digits.
	suppressing := true
	for _, idx := range zIndices {
		if suppressing && formattedInt[idx] == '0' {
			formattedInt[idx] = ' '
		} else {
			suppressing = false
		}
	}
	// Commas become spaces if everything to left is suppressed (i.e. all digit positions left of comma are spaces)
	// Left of first comma: indices 0,1
	if formattedInt[0] == ' ' && formattedInt[1] == ' ' {
		formattedInt[2] = ' '
	}
	// Left of second comma: indices 0,1,3,4,5
	if formattedInt[0] == ' ' && formattedInt[1] == ' ' && formattedInt[2] == ' ' && formattedInt[3] == ' ' && formattedInt[4] == ' ' && formattedInt[5] == ' ' {
		formattedInt[6] = ' '
	}

	result := string(formattedInt) + "." + fracPart
	if neg {
		// COBOL would put minus? Not needed for this program. Prepend minus in first space if possible.
		// Find last space before digit
		b := []byte(result)
		for i := len(b) - 1; i >= 0; i-- {
			if b[i] == ' ' {
				b[i] = '-'
				break
			}
			if b[i] != ',' && b[i] != '.' && b[i] >= '0' && b[i] <= '9' {
				continue
			}
		}
		result = string(b)
	}
	return result
}

func formatPic99(v int64) string {
	// PIC 99 => width 2 zero-padded
	// Keep low-order 2 digits
	if v < 0 {
		v = -v
	}
	v = v % 100
	return fmt.Sprintf("%02d", v)
}

func parseSchedRec(line string) SchedRec {
	// pad to 16
	if len(line) < 16 {
		line = line + strings.Repeat(" ", 16-len(line))
	}
	if len(line) > 16 {
		line = line[:16]
	}
	scAcct := line[0:4]
	scPrinStr := line[4:11]
	scRateStr := line[11:15]
	scYearsStr := line[15:16]

	// Parse digits
	var scPrin decimal.Decimal
	{
		s := strings.TrimSpace(scPrinStr)
		if s == "" {
			s = "0"
		}
		// digits only
		n := int64(0)
		for _, c := range s {
			if c >= '0' && c <= '9' {
				n = n*10 + int64(c-'0')
			}
		}
		// But s may be like "0010000" -> we parsed correctly
		// However s may contain spaces due to padding; already trimmed
		// Need to handle length 7 exactly: if s has non-digit we ignore
		// Build decimal with exponent -2
		scPrin = decimal.New(n, -2)
	}
	var scRate decimal.Decimal
	{
		s := strings.TrimSpace(scRateStr)
		if s == "" {
			s = "0"
		}
		n := int64(0)
		for _, c := range s {
			if c >= '0' && c <= '9' {
				n = n*10 + int64(c-'0')
			}
		}
		scRate = decimal.New(n, -2)
	}
	var scYears int64
	{
		s := strings.TrimSpace(scYearsStr)
		if s == "" {
			s = "0"
		}
		var n int64
		for _, c := range s {
			if c >= '0' && c <= '9' {
				n = n*10 + int64(c-'0')
			}
		}
		scYears = n % 10
	}
	return SchedRec{
		ScAcct:  scAcct,
		ScPrin:  scPrin,
		ScRate:  scRate,
		ScYears: scYears,
	}
}

func MAIN_PARA() {
	// OPEN INPUT SCHED-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not exists, treat as empty
		schedLines = []string{}
	} else {
		schedFile = f
		sc := bufio.NewScanner(f)
		// Don't use default split which strips \r; handle
		// Need to keep lines without newline
		for sc.Scan() {
			line := sc.Text()
			// Remove trailing \r if present (for CRLF)
			if strings.HasSuffix(line, "\r") {
				line = strings.TrimSuffix(line, "\r")
			}
			schedLines = append(schedLines, line)
		}
		f.Close()
	}
	schedIdx = 0

	READ_PARA()
	for !InputDone {
		PROCESS_PARA()
	}
	// CLOSE already done
	// DISPLAY "SCHEDULES: " WS-COUNT
	// WS-COUNT is PIC 99 -> zero padded 2 digits? But DISPLAY "SCHEDULES: " WS-COUNT => unedited numeric
	fmt.Printf("SCHEDULES: %s\n", formatPic99(WsCount))
}

func READ_PARA() {
	if schedIdx >= len(schedLines) {
		InputDone = true
		WsEofFlag = "Y"
		return
	}
	line := schedLines[schedIdx]
	schedIdx++
	SchedRecVar = parseSchedRec(line)
	InputDone = false
	WsEofFlag = "N"
}

func PROCESS_PARA() {
	// MOVE SC-PRIN TO WS-BAL : PIC 9(8)V99, truncate to 2 decimals, keep low-order 8 integer digits
	// SC-PRIN already scale 2, just store with overflow handling
	WsBal = storeWsBal(SchedRecVar.ScPrin)

	WsYear = 1
	for !(WsYear > SchedRecVar.ScYears) {
		// COMPUTE WS-BAL ROUNDED = WS-BAL * (1 + SC-RATE / 100)
		// SC-RATE /100 = SC-RATE *0.01 => shift -2
		factor := decimal.NewFromInt(1).Add(SchedRecVar.ScRate.Shift(-2))
		res := WsBal.Mul(factor)
		// ROUNDED to scale 2
		res = res.Round(2)
		WsBal = storeWsBal(res)
		WsBalEd = formatWsBalEd(WsBal)
		// DISPLAY SC-ACCT " Y" WS-YEAR " " WS-BAL-ED
		fmt.Printf("%s Y%s %s\n", SchedRecVar.ScAcct, formatPic99(WsYear), WsBalEd)
		WsYear++
	}
	WsBalEd = formatWsBalEd(WsBal)
	fmt.Printf("%s FINAL %s\n", SchedRecVar.ScAcct, WsBalEd)
	WsCount++
	READ_PARA()
}

func storeWsBal(v decimal.Decimal) decimal.Decimal {
	// PIC 9(8)V99 : 8 integer digits, 2 decimal, truncate toward zero to 2 decimals (but caller already rounded/truncated)
	// Keep low-order digits that fit
	v = v.Truncate(2)
	// For overflow, keep low-order 8 integer digits
	// Implement via modulo 10^8 for integer part
	neg := v.IsNegative()
	if neg {
		v = v.Neg()
	}
	// Split integer and fractional
	// fractional = v %1 *100
	// Use Shift
	intPart := v.Truncate(0)
	frac := v.Sub(intPart) // 0 <= frac <1
	// frac as cents: frac *100
	fracCents := frac.Shift(2).Truncate(0) // 0..99
	// Mod integer part by 100000000
	modBase := decimal.NewFromInt(100000000)
	// intPart.Mod is not always available, use remainder via Div
	// Use intPart mod modBase = intPart - trunc(intPart/modBase)*modBase
	if intPart.Cmp(modBase) >= 0 {
		q := intPart.Div(modBase).Truncate(0)
		intPart = intPart.Sub(q.Mul(modBase))
	}
	res := intPart.Add(fracCents.Shift(-2))
	if neg {
		res = res.Neg()
	}
	return res
}

func main() {
	MAIN_PARA()
}
